+// API keys and roles. Keys live in the data as `apiKeys` (docs/DATA.md).
+import { AppError } from "../errors.js";
+
+const COOK_ROUTES = new Set([
+  "POST /recipes/:id/cook",
+  "POST /batches/:id/waste",
+  "POST /temperatures",
+  "POST /stocktakes/:id/counts",
+]);
+
+/** Finds the key record for the request's `Authorization: Bearer <key>` header, or throws unauthorized. */
+export function authenticate(store, headers) {
+  const entry = Object.entries(headers ?? {}).find(([k]) => k.toLowerCase() === "authorization");
+  const m = /^Bearer\s+(\S+)\s*$/i.exec(String(entry?.[1] ?? ""));
+  const found = m && (store.data.apiKeys ?? []).find((k) => k.key === m[1]);
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** Throws forbidden unless `role` may call `method pattern`. */
+export function authorize(role, method, pattern) {
+  if (role === "manager") return;
+  if (method === "GET" && pattern === "/audit") throw new AppError("forbidden");
+  if (method === "GET" && (role === "viewer" || role === "cook")) return;
+  if (role === "cook" && COOK_ROUTES.has(`${method} ${pattern}`)) return;
+  throw new AppError("forbidden");
+}
