+++ b/tests/auth.test.js
@@ -0,0 +1,35 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { asKey, KEYS, rawApp } from "./helpers.js";
+
+test("missing or unknown keys are 401", async () => {
+  const { handle } = rawApp();
+  assert.equal((await handle({ path: "/items" })).body.error.code, "unauthorized");
+  const bad = await handle({ path: "/items", headers: { authorization: "Bearer nope" } });
+  assert.equal(bad.status, 401);
+});
+
+test("roles limit what a key may do", async () => {
+  const { handle } = rawApp();
+  const viewer = asKey(handle, KEYS.viewer);
+  const cook = asKey(handle, KEYS.cook);
+  assert.equal((await viewer({ path: "/items" })).status, 200);
+  const denied = await viewer({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  assert.equal(denied.status, 403);
+  assert.equal(denied.body.error.code, "forbidden");
+  assert.equal((await cook({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } })).status, 200);
+  assert.equal((await cook({ method: "POST", path: "/orders", body: {} })).status, 403);
+  assert.equal((await cook({ path: "/audit" })).status, 403);
+});
+
+test("changes are audited, newest first", async () => {
+  const { handle } = rawApp();
+  await asKey(handle, KEYS.cook)({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  await asKey(handle, KEYS.viewer)({ method: "POST", path: "/stocktakes", body: { location: "dry" } });
+  const log = await asKey(handle, KEYS.manager)({ path: "/audit" });
+  assert.equal(log.status, 200);
+  assert.deepEqual(log.body.map((e) => [e.key, e.method, e.path, e.status]), [
+    ["viewer", "POST", "/stocktakes", 403],
+    ["cook", "POST", "/recipes/1/cook", 200],
+  ]);
+});
